css:
.solviosim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7edf5;
    background: radial-gradient(circle at 18% 0%, #16243b 0%, #0b1322 55%, #070d18 100%);
    border-radius: 18px;
}

.solviosim-container * {
    box-sizing: border-box;
}

.solviosim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0a1a30 0%, #11304d 55%, #145c4f 100%);
    color: #eafff6;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #1d3a55;
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.45);
}

.solviosim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f4fff9;
}

.solviosim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #5fe0a8;
    background: rgba(95, 224, 168, 0.12);
    border: 1px solid rgba(95, 224, 168, 0.30);
    padding: 5px 14px;
    border-radius: 999px;
}

.solviosim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c6d6e6;
}

.solviosim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb6cf;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.solviosim-period-counter #currentDay,
.solviosim-period-counter #maxPeriods {
    font-weight: 800;
    color: #5fe0a8;
}

.solviosim-round-name {
    background: rgba(95, 224, 168, 0.14);
    color: #5fe0a8;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.solviosim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffc46b;
    background: rgba(255, 196, 107, 0.12);
    border: 1px solid rgba(255, 196, 107, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.solviosim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.solviosim-status-card {
    background: linear-gradient(160deg, #122035 0%, #0d1828 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #1d3148;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
    border-top: 4px solid #2f6fb0;
}

.solviosim-card-pnl { border-top-color: #5fe0a8; }
.solviosim-card-cred { border-top-color: #4aa3ff; }
.solviosim-card-comply { border-top-color: #b48bff; }
.solviosim-card-exposure { border-top-color: #ff7a59; }

.solviosim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8aa1bb;
}

.solviosim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f4fff9;
    font-variant-numeric: tabular-nums;
}

.solviosim-card-pnl .solviosim-value { color: #5fe0a8; }
.solviosim-card-cred .solviosim-value { color: #4aa3ff; }
.solviosim-card-comply .solviosim-value { color: #b48bff; }
.solviosim-card-exposure .solviosim-value { color: #ff7a59; }

.solviosim-sublabel {
    font-size: 0.76rem;
    color: #7e96b1;
    line-height: 1.35;
}

.solviosim-pnl-negative .solviosim-value { color: #ff6b5e; }
.solviosim-pnl-positive .solviosim-value { color: #5fe0a8; }

.solviosim-exposure-high { border-top-color: #ff4d4d; }
.solviosim-exposure-high .solviosim-value { color: #ff5c5c; }
.solviosim-exposure-low { border-top-color: #5fe0a8; }
.solviosim-exposure-low .solviosim-value { color: #5fe0a8; }

.solviosim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0a1626;
    border: 1px solid #1d3148;
    color: #d6e4f2;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.solviosim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #5fe0a8;
}

.solviosim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #122035 0%, #0d1828 100%);
    border-left: 5px solid #5fe0a8;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.solviosim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.solviosim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #f4fff9;
    margin-bottom: 6px;
}

.solviosim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c2d2e4;
}

.solviosim-briefing-text strong { color: #5fe0a8; }
.solviosim-briefing-text em { color: #ffc46b; font-style: italic; }

.solviosim-controls {
    background: linear-gradient(160deg, #101c2f 0%, #0c1727 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #1d3148;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.solviosim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f4fff9;
    border-bottom: 2px solid #1d3148;
    padding-bottom: 8px;
}

.solviosim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cfe0f1;
    margin: 14px 0 6px;
}

.solviosim-container select,
.solviosim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2a4361;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0e1c30;
    color: #eaf2fb;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.solviosim-container select:focus,
.solviosim-container input[type="number"]:focus {
    outline: none;
    border-color: #5fe0a8;
    box-shadow: 0 0 0 3px rgba(95, 224, 168, 0.18);
}

.solviosim-container select option {
    background-color: #0e1c30;
    color: #eaf2fb;
}

.solviosim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #5fe0a8;
}

.solviosim-range-readout,
.solviosim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb6cf;
    margin-top: 4px;
}

.solviosim-range-readout span:last-child,
.solviosim-alloc-readout span:nth-child(2) {
    color: #5fe0a8;
    font-weight: 800;
}

.solviosim-hint {
    font-size: 0.8rem;
    color: #7e96b1;
    margin-top: 4px;
    line-height: 1.4;
}

.solviosim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.solviosim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #0e1c30;
    border: 1px solid #22384f;
    border-radius: 9px;
    padding: 8px 12px;
}

.solviosim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #cfe0f1;
}

.solviosim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.solviosim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.solviosim-container .btn-primary {
    background: linear-gradient(135deg, #178a63 0%, #5fe0a8 100%);
    border: none;
    color: #07261b;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(23, 138, 99, 0.40);
}

.solviosim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.solviosim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2a4361;
    color: #9fb6cf;
    background: transparent;
}

.solviosim-coach {
    background: linear-gradient(160deg, #0a1626 0%, #0d1f1a 100%);
    color: #d8e8f4;
    border: 1px solid #1d3a3a;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.solviosim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #5fe0a8;
    margin-bottom: 8px;
}

.solviosim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.solviosim-coach-body strong { color: #5fe0a8; }
.solviosim-coach-body em { color: #ffc46b; font-style: italic; }

.solviosim-history,
.solviosim-chart {
    background: linear-gradient(160deg, #101c2f 0%, #0c1727 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #1d3148;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.solviosim-history h3,
.solviosim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f4fff9;
}

.solviosim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cfe0f1;
}

.solviosim-container table#usfHistoryTable th {
    background: #0e1c30;
    color: #5fe0a8;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #22384f;
}

.solviosim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #1a2a3e;
    color: #c2d2e4;
}

.solviosim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0d1929;
}

.solviosim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .solviosim-container {
        padding: 14px;
    }
    .solviosim-header h1 {
        font-size: 1.7rem;
    }
    .solviosim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .solviosim-value {
        font-size: 2rem;
    }
    .solviosim-clock {
        margin-left: 0;
    }
    .solviosim-period-counter {
        font-size: 0.88rem;
    }
    .solviosim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .solviosim-alloc-row {
        flex-wrap: wrap;
    }
    .solviosim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .solviosim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.solviosim-cm { background:#f7fafc; color:#12212f; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.solviosim-cm-head { text-align:center; border-bottom:1px solid #dde5ee; padding-bottom:14px; margin-bottom:16px; }
.solviosim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#5a6b7d; font-weight:700; }
.solviosim-cm-scorewrap { margin:8px 0 2px; }
.solviosim-cm-score { font-size:52px; font-weight:800; color:#0b7a4b; line-height:1; }
.solviosim-cm-score-max { font-size:20px; color:#8494a5; font-weight:600; }
.solviosim-cm-grade { font-size:19px; font-weight:700; color:#12212f; margin-top:4px; }
.solviosim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.solviosim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.solviosim-cm-met { background:#d6f2e2; color:#0b6b41; }
.solviosim-cm-fail { background:#fce0dc; color:#a4322a; }
.solviosim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.solviosim-cm-metric { background:#eef3f8; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.solviosim-cm-metric-val { font-size:22px; font-weight:800; color:#12212f; }
.solviosim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#5a6b7d; margin-top:3px; }
.solviosim-cm-insights { background:#eef3f8; border-radius:10px; padding:14px 18px; }
.solviosim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#5a6b7d; font-weight:700; margin-bottom:8px; }
.solviosim-cm-insights ul { margin:0; padding-left:18px; }
.solviosim-cm-insights li { font-size:14px; line-height:1.5; color:#2a3a4a; margin-bottom:7px; }

