(function() {
    'use strict';

    class SolvioAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Pay & Comply`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Solvio Pay SAS).
            this.VOLUME = 4.3;               // EUR 4.3B annual B2C payment volume
            this.EBITDA = 5.2;               // ~EUR 5.2M EBITDA line (6% of EUR 86M)
            this.FULL_SAVING = 9;            // ~EUR 9M full-migration card→A2A saving
            this.CLIMATE_BUDGET = 2.4;       // EUR 2.4M ring-fenced covenant budget
            this.COMPLIANCE_CAP = 1.9;       // EUR 1.9M top of the CSRD compliance band
            this.OFFSET_PRICE = 10;          // ~EUR 10 / tonne low-additionality offsets

            // Concept truths.
            this.TRUE_FRAME = `system`;
            this.TRUE_EXPOSURE = `covenant`;
            this.TRUE_RAIL = `hybrid`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    pnl: 0,                  // EUR M annual P&L impact vs status quo
                    cred: 20,                // investor & market trust in the green claim
                    comply: 15,              // assurable double-materiality CSRD readiness
                    exposure: 45,            // greenwashing / regulator / covenant risk (lower better)
                    budgetUsed: 0,           // EUR M of compliance budget committed
                    offsetHeavy: false,
                    overPromised: false,
                    pnlHistory: [0],
                    credHistory: [20],
                    complyHistory: [15],
                    exposureHistory: [45],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a click-through must not auto-win.
                state.decisions = {
                    frame: `parallel`,
                    exposureChoice: `cost`,
                    integration: 50,
                    rail: `a2a`,
                    migration: 50,
                    fraud: 0,
                    emissions: `later`,
                    abate: 0.8,
                    product: 0.8,
                    offset: 0.8,
                    align: `loose`,
                    disclosure: `glowing`,
                    assurance: 1.2,
                    press: `spin`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frameInput`);
                const ex = document.getElementById(`exposureInput`);
                const it = document.getElementById(`integrationInput`);
                if (fr) decisions.frame = fr.value;
                if (ex) decisions.exposureChoice = ex.value;
                if (it) decisions.integration = parseInt(it.value, 10);
                if (!Number.isFinite(decisions.integration) || decisions.integration < 0 || decisions.integration > 100) {
                    warn(`warn_integration_range`); return false;
                }
            } else if (round === 2) {
                const rl = document.getElementById(`railInput`);
                const mg = document.getElementById(`migrationInput`);
                const fd = document.getElementById(`fraudInput`);
                const em = document.getElementById(`emissionsInput`);
                if (rl) decisions.rail = rl.value;
                if (mg) decisions.migration = parseInt(mg.value, 10);
                if (fd) decisions.fraud = parseFloat(fd.value);
                if (em) decisions.emissions = em.value;
                if (!Number.isFinite(decisions.migration) || decisions.migration < 0 || decisions.migration > 100) {
                    warn(`warn_migration_range`); return false;
                }
                if (!Number.isFinite(decisions.fraud) || decisions.fraud < 0) {
                    warn(`warn_fraud_value`); return false;
                }
            } else if (round === 3) {
                const ab = document.getElementById(`abateInput`);
                const pr = document.getElementById(`productInput`);
                const of = document.getElementById(`offsetInput`);
                const al = document.getElementById(`alignInput`);
                if (ab) decisions.abate = parseFloat(ab.value);
                if (pr) decisions.product = parseFloat(pr.value);
                if (of) decisions.offset = parseFloat(of.value);
                if (al) decisions.align = al.value;
                const parts = [decisions.abate, decisions.product, decisions.offset];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.abate + decisions.product + decisions.offset) * 10) / 10;
                if (Math.abs(total - this.CLIMATE_BUDGET) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const di = document.getElementById(`disclosureInput`);
                const as = document.getElementById(`assuranceInput`);
                const pe = document.getElementById(`pressInput`);
                const cv = document.getElementById(`convictionInput`);
                if (di) decisions.disclosure = di.value;
                if (as) decisions.assurance = parseFloat(as.value);
                if (pe) decisions.press = pe.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let pnlDelta = 0, credDelta = 0, complyDelta = 0, exposureDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the triple bind as ONE system (Common Error 5: siloed decisions).
                switch (d.frame) {
                    case `system`: credDelta += 10; complyDelta += 6; exposureDelta -= 8; coachKey = `coach_r1_system`; break;
                    case `parallel`: exposureDelta += 4; coachKey = `coach_r1_parallel`; break;
                    case `sequential`: credDelta -= 2; exposureDelta += 5; coachKey = `coach_r1_sequential`; break;
                    case `reporting`: credDelta -= 4; complyDelta -= 4; exposureDelta += 8; coachKey = `coach_r1_reporting`; break;
                }

                // Name the biggest combined exposure (covenant + regulator + reputation).
                switch (d.exposureChoice) {
                    case `covenant`: complyDelta += 6; exposureDelta -= 8; if (d.frame === `system`) coachKey = `coach_r1_sharp`; break;
                    case `cost`: exposureDelta += 4; break;
                    case `press`: exposureDelta += 4; break;
                    case `none`: credDelta -= 4; exposureDelta += 10; coachKey = `coach_r1_none`; break;
                }

                if (d.integration >= 60) { credDelta += 6; exposureDelta -= 5; }
                else if (d.integration <= 25) { credDelta -= 5; exposureDelta += 6; coachKey = `coach_r1_lowintegration`; }

                summaryKey = (d.frame === `system` && d.exposureChoice === `covenant`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the rail — the P&L-dominant lever (Common Errors 1 & 2).
                const m = d.migration / 100;
                const fraudCost = d.fraud;                       // EUR M invested in adoption + fraud-ops
                // churnFactor: investment buys down the adoption/fraud churn on the new rail.
                let churnFactor = 1.0;
                if (d.fraud >= 2) churnFactor = 0.20;
                else if (d.fraud >= 1) churnFactor = 0.55;

                if (d.rail === `cards`) {
                    // Ignore the cost swing — the EUR 8–12M premium eats the EBITDA line.
                    pnlDelta -= 8; credDelta += 4; exposureDelta += 2; coachKey = `coach_r2_cards`;
                } else if (d.rail === `a2a`) {
                    // Full push. Headline saving, but quadratic churn if adoption isn't modelled.
                    pnlDelta += m * this.FULL_SAVING - (m * m) * 11 * churnFactor - fraudCost;
                    coachKey = (d.fraud <= 0 && m >= 0.6) ? `coach_r2_a2aheadline` : `coach_r2_a2a`;
                } else { // hybrid
                    // Phased, modelled adoption keeps card familiarity and halves churn.
                    pnlDelta += m * this.FULL_SAVING - (m * m) * 5 * churnFactor - fraudCost + 1;
                    credDelta += 3; complyDelta += 2; coachKey = `coach_r2_hybrid`;
                }

                // Adoption + fraud-ops investment also moves regulatory exposure (SCA/PSD2, AML).
                if (d.rail !== `cards`) {
                    if (d.fraud >= 2) exposureDelta -= 4;
                    else if (d.fraud <= 0) { exposureDelta += 5; if (coachKey === `coach_r2_a2a` || coachKey === `coach_r2_hybrid`) coachKey = `coach_r2_nofraud`; }
                }

                // Flag the emissions implication for the CSRD report (links R2→R4).
                switch (d.emissions) {
                    case `flag`: complyDelta += 8; exposureDelta -= 6; credDelta += 3; break;
                    case `later`: break;
                    case `ignore`: complyDelta -= 4; exposureDelta += 6; coachKey = `coach_r2_emisignore`; break;
                }

                summaryKey = (d.rail === `hybrid` && d.fraud >= 1 && d.emissions !== `ignore`) ? `sum_r2_good` :
                             (d.rail === `a2a` && d.fraud <= 0 ? `sum_r2_headline` : `sum_r2_weak`);
            } else if (round === 3) {
                // Allocate the EUR 2.4M climate budget (Common Error 3: offset-only).
                const a = d.abate, p = d.product, o = d.offset;

                credDelta += a * 7 + p * 4 - o * 5;
                exposureDelta += o * 9 - a * 5 - p * 2;
                complyDelta += a * 3 + p * 2 + o * 1;
                pnlDelta += p * 0.5;                              // the customer green product monetises a little

                // Align the spend with what the rail actually did to emissions (links R2→R3).
                switch (d.align) {
                    case `align`: credDelta += 8; exposureDelta -= 8; complyDelta += 5; break;
                    case `loose`: exposureDelta += 3; break;
                    case `ignore`: credDelta -= 5; exposureDelta += 8; complyDelta -= 3; coachKey = `coach_r3_ignorealign`; break;
                }

                if (o >= 2.0) { ds.offsetHeavy = true; coachKey = `coach_r3_offsetonly`; }
                else if (a >= 1.2 && o <= 0.6) { coachKey = `coach_r3_abate`; }
                else if (coachKey === `coach_default`) { coachKey = `coach_r3_mixed`; }

                summaryKey = (a >= p && a >= o && o <= 0.6 && d.align === `align`) ? `sum_r3_good` :
                             (o >= 2.0 ? `sum_r3_offset` : `sum_r3_weak`);
            } else if (round === 4) {
                // Select CSRD disclosures & face the press (Common Error 4: over-promising).
                switch (d.disclosure) {
                    case `honest`: complyDelta += 14; credDelta += 8; exposureDelta -= 10; coachKey = `coach_r4_honest`; break;
                    case `glowing`: complyDelta -= 6; credDelta += 4; exposureDelta += 12; ds.overPromised = true; coachKey = `coach_r4_glowing`; break;
                    case `minimal`: complyDelta += 2; credDelta -= 6; exposureDelta += 6; coachKey = `coach_r4_minimal`; break;
                }

                // Assurance scope drawn from the CSRD compliance budget.
                spend += d.assurance;
                if (d.assurance >= 1.7) { complyDelta += 12; exposureDelta -= 8; }
                else if (d.assurance >= 1.2) { complyDelta += 6; exposureDelta -= 3; }
                else { complyDelta -= 2; exposureDelta += 4; }

                // Holding statement for the journalist and the impact investor.
                switch (d.press) {
                    case `evidence`: credDelta += 12; exposureDelta -= 12; if (d.disclosure === `honest`) coachKey = `coach_r4_facedown`; break;
                    case `spin`: credDelta -= 4; exposureDelta += 8; coachKey = `coach_r4_spin`; break;
                    case `silence`: credDelta -= 8; exposureDelta += 6; coachKey = `coach_r4_silence`; break;
                }

                if (d.conviction >= 60) { credDelta += 5; exposureDelta -= 4; }
                else if (d.conviction <= 25) { credDelta -= 5; exposureDelta += 5; }

                summaryKey = (d.disclosure === `honest` && d.assurance >= 1.2 && d.press === `evidence`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: only the CSRD compliance budget is metered here
            // (the EUR 2.4M climate budget is the covenant ring-fence handled in R3).
            ds.budgetUsed = Math.min(this.COMPLIANCE_CAP, Math.round((ds.budgetUsed + spend) * 10) / 10);

            // Apply deltas, clamped with headroom (KPIs start low; exposure 0–100, lower better).
            ds.pnl = Math.round((ds.pnl + pnlDelta) * 10) / 10;
            ds.cred = Math.max(0, Math.min(100, Math.round(ds.cred + credDelta)));
            ds.comply = Math.max(0, Math.min(100, Math.round(ds.comply + complyDelta)));
            ds.exposure = Math.max(0, Math.min(100, Math.round(ds.exposure + exposureDelta)));

            ds.pnlHistory.push(ds.pnl);
            ds.credHistory.push(ds.cred);
            ds.complyHistory.push(ds.comply);
            ds.exposureHistory.push(ds.exposure);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                pnl: ds.pnl,
                pnlDelta: Math.round(pnlDelta * 10) / 10,
                cred: ds.cred,
                credDelta: Math.round(credDelta),
                comply: ds.comply,
                complyDelta: Math.round(complyDelta),
                exposure: ds.exposure,
                exposureDelta: Math.round(exposureDelta),
                budgetUsed: ds.budgetUsed,
                offsetHeavy: ds.offsetHeavy,
                overPromised: ds.overPromised,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware EUR: English "€2.4M" (symbol before), Spanish "2,4 M€" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M€`;
            }
            return `${sign}€${abs.toFixed(1)}M`;
        }

