            // Integration slider readout.
            const it = document.getElementById(`integrationInput`);
            const itReadout = document.getElementById(`integrationReadout`);
            if (it && itReadout) {
                itReadout.textContent = it.value;
                it.addEventListener(`input`, function() { itReadout.textContent = it.value; });
            }

            // Migration slider readout.
            const mg = document.getElementById(`migrationInput`);
            const mgReadout = document.getElementById(`migrationReadout`);
            if (mg && mgReadout) {
                mgReadout.textContent = mg.value;
                mg.addEventListener(`input`, function() { mgReadout.textContent = mg.value; });
            }

            // Climate-budget live total (must hit EUR 2.4M).
            const allocIds = [`abateInput`, `productInput`, `offsetInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.solviosim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.CLIMATE_BUDGET) > 0.001) ? `#ff6b5e` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

