        _composite(ds) {
            const cred = Math.round(ds.cred);
            const comply = Math.round(ds.comply);
            const exposure = Math.round(ds.exposure);
            const pnl = ds.pnl;
            const pnlScore = Math.max(-25, Math.min(25, pnl * 2.5));
            return Math.round(cred * 0.32 + comply * 0.30 + (100 - exposure) * 0.30 + (pnlScore + 25) * 0.16);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const pnl = ds.pnl;
            const cred = Math.round(ds.cred);
            const comply = Math.round(ds.comply);
            const exposure = Math.round(ds.exposure);

            // Composite: credibility, CSRD readiness, low exposure, plus a P&L bonus
            // (normalised: each EUR M of P&L worth ~2.5 points, capped at ±25).
            const composite = this._composite(ds);

            const solvent = pnl >= 0;
            const credible = cred >= 60 && exposure <= 35;
            const assured = comply >= 60;
            const greenwashed = ds.offsetHeavy || exposure >= 65 || (ds.overPromised && comply < 50);

            let performanceKey = `grade_unsolved`;
            if (solvent && credible && assured && composite >= 75) performanceKey = `grade_resilient`;
            else if (credible && assured) performanceKey = `grade_covenant`;
            else if (greenwashed) performanceKey = `grade_greenwash`;
            else if (!solvent && pnl <= -6) performanceKey = `grade_pnlblown`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const met = solvent && credible && assured && composite >= 75;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (solvent && credible && assured) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (greenwashed) insights.push(window.mySimulation.t(`insight_greenwash`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (pnl < 0) insights.push(window.mySimulation.t(`insight_pnl_negative`));
            else if (pnl >= 3) insights.push(window.mySimulation.t(`insight_pnl_strong`));
            if (ds.overPromised) insights.push(window.mySimulation.t(`insight_overpromise`));
            if (comply < 45) insights.push(window.mySimulation.t(`insight_unassured`));
            if (exposure <= 25 && cred >= 65) insights.push(window.mySimulation.t(`insight_trusted`));

            return {
                pnl: pnl,
                cred: cred,
                comply: comply,
                exposure: exposure,
                solvent: solvent,
                credible: credible,
                assured: assured,
                greenwashed: greenwashed,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="solviosim-cm-badge ` + (s.met ? `solviosim-cm-met` : `solviosim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.greenwashed) badges.push(`<span class="solviosim-cm-badge solviosim-cm-fail">` + t(`cm_fail_greenwash`) + `</span>`);
            if (s.solvent === false) badges.push(`<span class="solviosim-cm-badge solviosim-cm-fail">` + t(`cm_fail_pnl`) + `</span>`);
            if (s.credible === false || s.assured === false) badges.push(`<span class="solviosim-cm-badge solviosim-cm-fail">` + t(`cm_fail_covenant`) + `</span>`);
            const kpi = (label, val) => `<div class="solviosim-cm-metric"><div class="solviosim-cm-metric-val">` + val + `</div><div class="solviosim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_pnl`), this._fmtMoney(s.pnl != null ? s.pnl : 0)) + kpi(t(`cm_cred`), (s.cred != null ? s.cred : 0)) + kpi(t(`cm_comply`), (s.comply != null ? s.comply : 0)) + kpi(t(`cm_exposure`), (s.exposure != null ? s.exposure : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="solviosim-cm">`
                + `<div class="solviosim-cm-head"><div class="solviosim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="solviosim-cm-scorewrap"><span class="solviosim-cm-score">` + score + `</span><span class="solviosim-cm-score-max">/100</span></div>`
                + `<div class="solviosim-cm-grade">` + grade + `</div>`
                + `<div class="solviosim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="solviosim-cm-metrics">` + kpis + `</div>`
                + `<div class="solviosim-cm-insights"><div class="solviosim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.offsetHeavy) return window.mySimulation.t(`hint_offset`);
            if (ds.overPromised) return window.mySimulation.t(`hint_overpromise`);
            if (ds.pnl <= -4 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_pnl`);
            if (ds.exposure >= 65) return window.mySimulation.t(`hint_exposure`);
            if (state.currentPeriod >= 3 && ds.comply < 40) return window.mySimulation.t(`hint_comply`);
            if (ds.cred >= 65 && ds.comply >= 60 && ds.exposure <= 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

